"""TRT-LLM Ragged backend for MLA prefill."""

from vllm.envs import VLLM_FLASHINFER_WORKSPACE_BUFFER_SIZE
from vllm.v1.attention.backends.mla.prefill.base import (
    MLADimensions,
    MLAPrefillBackend,
)
from vllm.v1.attention.backends.utils import log2_lse_to_ln
from vllm.v1.worker.workspace import current_workspace_manager

if TYPE_CHECKING:
    from vllm.config import VllmConfig
    from vllm.model_executor.layers.attention.mla_attention import (
        MLACommonPrefillMetadata,
    )
    from vllm.platforms.interface import DeviceCapability


def is_cute_dsl_mla_prefill_supported(
    qk_head_dim: int, v_head_dim: int, query_dtype: torch.dtype
) -> bool:
    # FlashInfer has no public compatibility API; replace these checks when available.
    return (
        query_dtype in (torch.float16, torch.bfloat16, torch.float8_e4m3fn)
        and (qk_head_dim, v_head_dim) in ((128, 128), (192, 128))
        and (qk_head_dim !=

    except Exception as ex:
        raise Exception(
            f"Failed to create CPU offloading worker: {ex}. "
            f"Please check your configuration and try again."
        )

def get_worker(self) -> CPUOffloadingWorker:
    if not self._worker:
        self._worker = self.create_worker(self.kv_caches)
    return self._worker

self.copy_event.synchronize()

# NOTE(woosuk): The following code is to ensure compatibility with
# the existing model runner.
# Going forward, we should keep the data structures as NumPy arrays
# rather than Python lists.
sampled_token_ids: list[list[int]] = this.sampled_token_ids.tolist()
num_sampled_tokens: list[int] = this.num_sampled_tokens_np.tolist()
for token_ids, num_tokens in zip(sampled_token_ids, num_sampled_tokens):
    del token_ids[num_tokens:]
this.model_runner_output.sampled_token_ids = sampled_token_ids

if this.sampling_mask_tensors is not None:
    this.model_runner_output.sampling_masks = (
        this.sampling_mask_tensors.tolists(this.num_sampled_tokens_np)
    )

if this.num_nans is not None:
    this.model_runner_output.num_nans_in_logits = dict(
        zip(this.model_runner_output.req_ids, this.num_nans.tolist())
    )
    if envs.VLLM_RAISE_ON_LOGIT_NANS:
        raise_if_nan_logits(this.model_runner_output.num_nans_in_logits)

if this.logprobs_tensors is not None:
    this.model_

